CREATE TABLE public.designer_accounts (slug text PRIMARY KEY, user_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.designer_accounts TO authenticated;
GRANT ALL ON public.designer_accounts TO service_role;
ALTER TABLE public.designer_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Designer reads own assignment" ON public.designer_accounts FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL, designer_slug text NOT NULL, design_slug text, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.conversations TO authenticated;
GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read conversations" ON public.conversations FOR SELECT TO authenticated USING (customer_id = auth.uid() OR EXISTS (SELECT 1 FROM public.designer_accounts a WHERE a.slug = designer_slug AND a.user_id = auth.uid()));
CREATE POLICY "Customers start conversations" ON public.conversations FOR INSERT TO authenticated WITH CHECK (customer_id = auth.uid());
CREATE TABLE public.designer_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL, body text NOT NULL, selection jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.designer_messages TO authenticated;
GRANT ALL ON public.designer_messages TO service_role;
ALTER TABLE public.designer_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read messages" ON public.designer_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = conversation_id));
CREATE POLICY "Participants send messages" ON public.designer_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = conversation_id));
CREATE INDEX designer_messages_conversation_idx ON public.designer_messages(conversation_id, created_at);
CREATE INDEX conversations_customer_idx ON public.conversations(customer_id);